--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `order_id` varchar(64) NOT NULL,
  `client_id` varchar(32) NOT NULL,
  `destination_x` smallint unsigned NOT NULL,
  `destination_y` smallint unsigned NOT NULL,
  `packages` int unsigned NOT NULL,
  `registered_at` timestamp(6) NOT NULL,
  `deadline` timestamp(6) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'REGISTERED',
  `delivery_type` varchar(20) NOT NULL DEFAULT 'REGULAR',
  `promised_hours` smallint unsigned NOT NULL DEFAULT '36',
  `delivered_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`order_id`),
  CONSTRAINT `chk_orders_deadline` CHECK ((`deadline` > `registered_at`)),
  CONSTRAINT `chk_orders_deadline_consistency` CHECK ((`deadline` = (`registered_at` + interval `promised_hours` hour))),
  CONSTRAINT `chk_orders_delivered_at` CHECK (((`delivered_at` is null) or (`delivered_at` >= `registered_at`))),
  CONSTRAINT `chk_orders_delivery_type` CHECK ((`delivery_type` in (_latin1'REGULAR',_latin1'PRIORITY'))),
  CONSTRAINT `chk_orders_destination_x` CHECK ((`destination_x` between 0 and 70)),
  CONSTRAINT `chk_orders_destination_y` CHECK ((`destination_y` between 0 and 50)),
  CONSTRAINT `chk_orders_packages` CHECK ((`packages` > 0)),
  CONSTRAINT `chk_orders_promised_hours` CHECK ((((`delivery_type` = _latin1'REGULAR') and (`promised_hours` = 36)) or ((`delivery_type` = _latin1'PRIORITY') and (`promised_hours` in (4,8,12,18))))),
  CONSTRAINT `chk_orders_status` CHECK ((`status` in (_latin1'REGISTERED',_latin1'ASSIGNED',_latin1'IN_TRANSIT',_latin1'DELIVERED')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

