--
-- Table structure for table `plans`
--

DROP TABLE IF EXISTS `plans`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `plans` (
  `plan_id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `execution_id` bigint unsigned NOT NULL,
  `plan_type` varchar(20) NOT NULL,
  `created_at` timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  `feasible` tinyint(1) NOT NULL,
  `total_distance_km` decimal(14,2) NOT NULL DEFAULT '0.00',
  `total_cost` decimal(14,2) NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`plan_id`),
  KEY `idx_plans_execution` (`execution_id`),
  KEY `idx_plans_created_at` (`created_at`),
  CONSTRAINT `fk_plans_execution` FOREIGN KEY (`execution_id`) REFERENCES `scenario_executions` (`execution_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `chk_plans_cost` CHECK ((`total_cost` >= 0)),
  CONSTRAINT `chk_plans_distance` CHECK ((`total_distance_km` >= 0)),
  CONSTRAINT `chk_plans_type` CHECK ((`plan_type` in (_latin1'INITIAL',_latin1'REPLANNING')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

